#!/opt/pilot-tools/codenib/bin/python
import json,sys
from pathlib import Path
p=Path('/opt/g1-state/client-stub.json')
a=sys.argv[1:]
if a[:2]==['mcp','get']:
    if not p.exists():print('MCP server not found');sys.exit(1)
    v=json.loads(p.read_text())
    print('  Scope: Local config\n  Type: stdio\n  Command: '+v[0]+'\n  Args: '+' '.join(v[1:]))
elif a[:2]==['mcp','add'] and '--' in a:
    p.parent.mkdir(parents=True,exist_ok=True);p.write_text(json.dumps(a[a.index('--')+1:]))
else:sys.exit(2)
